  ('Snarl up', '', 'Entangle.', 'My line was all [snarled up] after I caught that last fish.', '⬆️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Sneak out', '', 'Depart furtively.', 'Although the thieves tried to [sneak out] after dark, we were ready for them.', '📤', array['Phrasal verb','Action','How things are done']::text[]),
  ('Sneak up on', '', 'Approach someone furtively.', 'Dave tried to [sneak up on] the guard, but was seen anyway.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Sniff around', '', 'Look around to see how good something is or to try to find something better.', 'I [sniffed around] to see if I could find a better deal.', '🔄', array['Phrasal verb','Action','Looking & seeing']::text[]),
  ('Sniff at', '', 'Disapprove or be scornful.', 'A job opportunity like that is not to be [sniffed at].', '📌', array['Phrasal verb','Action','How things are done']::text[]),
  ('Sniff out', '', 'Find something by smell (usually for dogs).', 'Customs use dogs to [sniff out] illegal drugs being smuggled in.', '📤', array['Phrasal verb','Action','Looking & seeing']::text[]),
  ('Sniff out', 'meaning 2', 'Find out information, especially when people don''t want anyone to know.', 'Our rivals are trying to [sniff out] our plans for expansion.', '📤', array['Phrasal verb','Action','Looking & seeing','≈ Want']::text[]),
  ('Snitch on', '', 'Divulge secrets, inform authorities about someone.', 'Reggie was caught after someone [snitched on] him to the teacher.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Snuff out', '', 'Extinguish a small flame by covering it.', 'I [snuffed out] the candles before I went to bed.', '📤', array['Phrasal verb','Action','How things are done']::text[]),
  ('Snuff out', 'meaning 2', 'End something suddenly.', 'I messed up the first question, which [snuffed out] my chances of getting a good grade.', '📤', array['Phrasal verb','Action','Time & change']::text[]),
  ('Soften up', '', 'Weaken.', 'The bombardment [softened up] their defenses; I think we can move in tomorrow.', '⬆️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Soften up', 'meaning 2', 'Do things to please someone in the hope that they will do what you want.', 'I paid for everything to [soften] them [up] before they made the decision.', '⬆️', array['Phrasal verb','Action','How things are done','≈ Want']::text[]),
  ('Soldier on', '', 'Continue even when things get difficult.', 'Life got hard for my dog when he went blind, but he just [soldiered on] and never complained.', '🔛', array['Phrasal verb','Action','Time & change','≈ Without stopping']::text[]),
  ('Sound off', '', 'To express your opinions forcefully.', 'He [sounded off] about the quality of the food.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Sound out', '', 'Check what someone thinks about an issue, idea, etc.', 'You should [sound] her [out] to get her opinion before you go ahead with the plan.', '📤', array['Phrasal verb','Action','Saying & thinking','≈ Think of','≈ Look']::text[]),
  ('Spaff away', '', 'Waste (money, time, resources, etc).', 'The council is [spaffing away] our taxes on bonuses and consultants.', '↔️', array['Phrasal verb','Action','Money & work','Time & change']::text[]),
  ('Spark off', '', 'Cause something, usually unpleasant, to happen.', 'The riot was [sparked off] by the police raid on the club.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Spark up', '', 'Light a cigarette or joint.', 'They [sparked up] in a no smoking area.', '⬆️', array['Phrasal verb','Action','Light & sound','≈ Join']::text[]),
  ('Speak out', '', 'Talk openly and freely.', 'People are afraid to [speak out] in oppressive political regimes.', '📤', array['Phrasal verb','Action','Saying & thinking']::text[]),
  ('Speak up', '', 'Talk more loudly.', 'They couldn''t hear the speaker and asked him to [speak up] a bit.', '⬆️', array['Phrasal verb','Action','Saying & thinking','Size, amount & distance']::text[]),
  ('Spell out', '', 'Explain something in great detail.', 'He won''t understand you unless you [spell] everything [out] for him.', '📤', array['Phrasal verb','Action','Saying & thinking','≈ Clear']::text[]),
  ('Spell out', 'meaning 2', 'Write or say the individual letters that make up a word.', 'I had to [spell] my surname [out] to him as he didn''t know how to spell it.', '📤', array['Phrasal verb','Action','Saying & thinking','Words & books']::text[]),
  ('Spew out', '', 'Expel, throw out.', 'The volcano is [spewing out] lava and hot gases.', '📤', array['Phrasal verb','Action','How things are done']::text[]),
  ('Spill out', '', 'When large numbers of people leave a place at the same time.', 'The crowd [spilled out] onto the streets after the match had ended.', '📤', array['Phrasal verb','Action','Ways of moving','Time & change']::text[]),
  ('Spill out', 'meaning 2', 'Come or flow out of a box, container, etc.', 'The container was cracked and the chemicals [spilled out].', '📤', array['Phrasal verb','Action','Ways of moving']::text[]),
  ('Spill out', 'meaning 3', 'Express or display emotions openly.', 'I let my frustration [spill out].', '📤', array['Phrasal verb','Action','How things are done']::text[]),
  ('Spill over', '', 'When something bad has a wider impact on other people or situations.', 'The protests and demonstrations have [spilled over] into neighbouring states.', '🌉', array['Phrasal verb','Action','How things are done']::text[]),
  ('Spill over', 'meaning 2', 'Flow over the edge or top of a container.', 'I forgot to turn the tap off and the water [spilled over].', '🌉', array['Phrasal verb','Action','How things are done']::text[]),
