  ('Spirit off', '', 'Remove someone secretly from a place.', 'They [spirited] him [off] before any trouble started.', '🔛', array['Phrasal verb','Action','Places & travel','Size, amount & distance']::text[]),
  ('Spit it out', '', 'An informal way of telling someone to say something they are unwilling to say.', 'Hurry up, [spit it out]! I can''t wait all day for the truth.', '📤', array['Phrasal verb','Action','Saying & thinking']::text[]),
  ('Spit out', '', 'Say something angrily.', 'He [spat] her name [out] when he saw her arrive.', '📤', array['Phrasal verb','Action','Saying & thinking']::text[]),
