  ('Sponge down', '', 'Clean something with a sponge.', 'I''ll [sponge] it [down] before putting it away.', '⬇️', array['Phrasal verb','Action','Homes & buildings']::text[]),
  ('Sponge off', '', 'Accept free food and support without any shame or qualms.', 'Let’s go to New York, we can always [sponge off] my brother there.', '🔛', array['Phrasal verb','Action','Food & drink','Getting along','≈ Help','≈ Agreed']::text[]),
  ('Sponge on', '', 'Accept or get money without doing any work.', 'A lot of people are [sponging on] the state by claiming benefits they''re not entitled to.', '🔛', array['Phrasal verb','Action','Money & work','≈ Agreed']::text[]),
