  ('Spring up', '', 'Appear suddenly.', 'Charity shops are [springing up] in the recession.', '⬆️', array['Phrasal verb','Action','How things are done']::text[]),
  ('Spruce up', '', 'To smarten, make something neat and tidy.', 'We [spruced] the flat [up] before we put it on the market.', '⬆️', array['Phrasal verb','Action','Homes & buildings']::text[]),
  ('Spur on', '', 'Encourage someone to continue.', 'The thought of the bonus [spurred] her [on] to complete the work on time.', '🔛', array['Phrasal verb','Action','Time & change','≈ Without stopping','≈ Brave']::text[]),
  ('Square away', '', 'Finish or sort something out.', 'There are few things I have to [square away] before I can leave.', '↔️', array['Phrasal verb','Action','Time & change']::text[]),
  ('Square off', '', 'Confront someone or prepare to fight them.', 'The two drunks [squared off] and the barman had to intervene before a fight broke out.', '🔛', array['Phrasal verb','Action','How things are done']::text[]),
  ('Square off against', '', 'Confront someone or prepare to fight them.', 'They [squared off against] the police when they arrived.', '📌', array['Phrasal verb','Action','How things are done']::text[]),
  ('Square up', '', 'Pay back a debt.', 'Can I [square up] with you for last night?', '⬆️', array['Phrasal verb','Action','Money & work']::text[]),
  ('Square up', 'meaning 2', 'Confront someone or prepare to fight them.', 'The companies are [squaring up] for a fight.', '⬆️', array['Phrasal verb','Action','How things are done']::text[]),
